"pkglib.variant.help": "Ha több csomag is ugyanannak a játéknak a frissítése vagy DLC-je, válassz pontosan egyet a tömeges Összes telepítése gombhoz. Kapcsold ki, hogy kihagyd. A sor Telepítés gombja mindig csak ezt a csomagot telepíti.",
// Kimondva, nem felismerve: egyetlen fejlécmező sem különbözteti meg
// a fake csomagot a retailtől (minden jelölt marker jelen van a valódi
// Sony csomagokon is), ezért a képernyő megnevezi az előfeltételt, és
// az olvasóra bízza a döntést.
"pkglib.fpkgsupport.title": "Fake csomagot (FPKG) telepítesz?",
"pkglib.fpkgsupport.lead": "Egy PS5 fake csomag csak akkor települ, ha a fake-csomag támogatás már be van töltve a konzolra. Töltsd be mindhármat, ebben a sorrendben, telepítés előtt:",
"pkglib.fpkgsupport.kstuff": "— az a build, ami PS5 fake-csomag támogatást tartalmaz",
"pkglib.fpkgsupport.ppr": "— alkalmazza a PPR plaintext / no-auth patchet",
"pkglib.fpkgsupport.smp": "— a csatolási réteg, ami regisztrálja a telepített címet",
"pkglib.fpkgsupport.tail": "Ezek nélkül a konzol elutasítja a telepítést, vagy elfogadja, majd nem sikerül csatolnia a játékot. A retail és a debug csomagoknak egyikre sincs szükségük — ha ezt telepíted, hagyd figyelmen kívül ezt a megjegyzést.",
"pkglib.installnote.title": "Hogyan működik a telepítés",
"pkglib.installnote.body": "A ps5upload a csomagot a PS5-ön futó saját telepítőjének adja át, és csak akkor jelzi telepítettnek, amikor a konzol a teljes csomagot beolvasta; egy javításnak ráadásul emelnie kell a játék verzióját. Ha egy telepítés meghiúsul, a csomag megmarad, így újrapróbálhatod. FW 12+ és rendszercsomagok esetén továbbra is szükség lehet a PS5 Beállítások → Rendszer → Hibakeresési beállítások → Játék → Package Installer menüjére.",
"pkglib.error": "Valami elromlott",
"pkglib.delete.confirmTitle": "Törlöd: {name}?",
"pkglib.delete.confirmBody": "Ez véglegesen eltávolítja a feltöltött .pkg fájlt ({size}) a PS5-ödről. A már telepített játékmásolat telepítve marad; a .pkg-t csak újratelepítéshez kell majd újra feltöltened.",
"pkglib.footer.count": "{n} csomag",
"pkglib.footer.size": "{size} a PS5-ön",
"pkglib.clearFinished": "Kész elemek törlése ({n})",
"pkglib.installAll": "Összes telepítése",
"pkglib.installAll.hint": "Minden staged csomag telepítése, alapjáték a frissítések és DLC előtt",
"pkglib.installAll.what": "Mi az Összes telepítése?",
"pkglib.installAll.whatBody": "Az Összes telepítése minden kész csomagot sorrendben futtat: alapjáték → frissítések → DLC. Ha két azonos verziójú frissítésed van (vagy két egymással ütköző DLC csomagod), a sor jelölőnégyzetével válaszd ki, melyiket telepítse ez a konzol — csoportonként csak egyet. Kapcsold ki, hogy kihagyd azt a csoportot. Egy sor Telepítés gombja mindig csak azt a csomagot telepíti.",
"pkglib.clearAll": "Összes törlése",
