payloads_essentials_title: "Ajánlott a ps5upload mellé",
payloads_essentials_body: "Ha most állítasz be egy konzolt először, ez a három fedi le a ps5upload legtöbb elvárását: kstuff-lite (a legtöbb homebrew által igényelt kernelpatchek), ShadowMount+ (játékképek csatolása tárhelyről) és nanoDNS (a konzol távoltartása a Sony frissítési útvonalától). Minden más ezen a listán opcionális.",
