library_move_retry: "Áthelyezés újrapróbálása",
volumes_pkg_copies_here: "A csomagmásolatok itt vannak",
volumes_store_pkg_copies: "Csomagmásolatok tárolása itt",
volumes_pkg_copies_hint: "Mit csinál ez a választás: a „Feltöltés és telepítés” először a PS5-re másolja a .pkg fájlt, majd abból a másolatból telepít. Ez csak azt adja meg, melyik meghajtón legyenek ezek a másolatok. Azt nem változtatja meg, hová települnek a játékok (ezt a PS5 a saját Tárhely beállításaiban dönti el), a „Streamelés és telepítés” pedig egyáltalán nem tart meg másolatot. Ha a választott meghajtó nincs csatlakoztatva, a másolatok a belső tárhelyre kerülnek.",
saves_auto_folder_label: "Mentési mappa",
captures: "Képernyőképek és klipek",
captures_title: "Felvételek",
"arcpkg.choose": "Archívum kiválasztása…",
"arcpkg.help": "Olyan .zip, .7z vagy .rar fájlhoz, amely bármely mappájában egy vagy több .pkg fájlt tartalmaz. Csak a csomagok lesznek kibontva, egyenesen a PS5-re (ezen a számítógépen semmi nem lesz kicsomagolva), majd egyenként települnek: előbb az alapjáték, aztán a frissítése, végül a DLC. A többrészes RAR (.part1.rar, .part2.rar…) támogatott: válaszd az első részt, a többit pedig tartsd mellette. A jelszót akkor kérjük, ha a RAR-hoz szükség van rá; a jelszavas ZIP és 7z nem támogatott.",
"arcpkg.keepsRunning": "Ez akkor is fut tovább, ha másik képernyőt nyitsz meg, és a Feladatok között is látszik.",
"arcpkg.notArchive": "Ez a fájl nem .zip, .7z vagy .rar archívum.",
"arcpkg.pick": "Válassz egy archívumot",
"arcpkg.title": "Csomagok telepítése archívumból",
"install.library.title": "Csomagmásolatok a PS5-ön",
"install.stream.file.help": "Válassz egy .pkg vagy .fpkg fájlt, vagy húzd az ablak bármely pontjára. Tartsd nyitva az alkalmazást, amíg a telepítés be nem fejeződik; a folyamat a fenti sorban és a Feladatok között látszik.",
"install.stream.file.title": "Csomagfájl telepítése",
"install.tab.stream.lead": "A PS5 közvetlenül erről a számítógépről vagy egy hivatkozásról telepít. Előtte nem kerül másolat a PS5-re, így ott nincs szükség szabad helyre, és ez a telepítés legmegbízhatóbb módja.",
"install.tab.upload.lead": "A csomag először a PS5-re másolódik, majd abból a másolatból települ. Akkor használd, ha a PS5 nem éri el ezt a számítógépet (a streamelés hálózati hibával megszakad), vagy ha a csomagokat a PS5-ön szeretnéd tartani, hogy később e számítógép nélkül is újratelepíthesd őket.",
"install.upload.file.browser": "Ahhoz, hogy innen csomagot másolj a PS5-re, az asztali alkalmazás kell. A webes felületen használd a Streamelés és telepítés lapot, vagy telepítsd lent a PS5-ön már meglévő csomagokat.",
"install.upload.file.help": "Válassz egy .pkg vagy .fpkg fájlt. A másolathoz a teljes csomagnak megfelelő szabad hely kell a PS5-ön, és az alábbi listában marad, amíg nem törlöd.",
"install.upload.file.title": "Csomag másolása a PS5-re és telepítése",
"linkcard.confirm.direct": "A PS5 maga tölti le a csomagot a hivatkozásról, és telepíti. Indítás után erre a számítógépre már nincs szükség, a folyamat pedig a PS5-ön (Letöltések) látszik, nem itt. Ha a PS5 nem éri el a hivatkozást, az alkalmazás ezen a számítógépen keresztül továbbítja. Egy már telepített játékra való újratelepítés eltávolíthatja azt, ha a Sony telepítője hibázik. Csak olyan csomagok hivatkozását használd, amelyekben megbízol, és amelyeket jogod van telepíteni.",
"linkcard.confirm.download": "Ez a számítógép előbb lemezre menti a teljes csomagot, majd telepíti a PS5-re. Mindkét lépés végéig bekapcsolva kell maradnia, és kell rajta szabad hely a csomagnak. Egy már telepített játékra való újratelepítés eltávolíthatja azt, ha a Sony telepítője hibázik. Csak olyan csomagok hivatkozását használd, amelyekben megbízol, és amelyeket jogod van telepíteni.",
"linkcard.confirm.stream": "Ez a számítógép letölti a csomagot, és azonnal továbbadja a PS5-nek, ezért a telepítés végéig bekapcsolva és kapcsolatban kell maradnia. Lemezre semmi nem kerül. Egy már telepített játékra való újratelepítés eltávolíthatja azt, ha a Sony telepítője hibázik. Csak olyan csomagok hivatkozását használd, amelyekben megbízol, és amelyeket jogod van telepíteni.",
"linkcard.confirm.title": "Telepítés erről a hivatkozásról?",
"linkcard.fact.awake": "Ne hagyd elaludni ezt a számítógépet",
"linkcard.fact.can_close": "Bezárhatod az alkalmazást",
"linkcard.fact.disk": "Itt lemezterület kell hozzá",
