"linkcard.fact.progress_here": "A folyamat itt látszik",
"linkcard.fact.progress_ps5": "A folyamat a PS5-ön látszik",
"linkcard.forget": "Eltávolítás a listáról",
"linkcard.help": "Illessz be egy .pkg fájlra mutató közvetlen hivatkozást. Előzetesen semmi nem másolódik a PS5-re, így egy 100 GB-os játéknak nem kell ott plusz hely.",
"linkcard.how": "Hogyan töltődjön le?",
"linkcard.insecure": "Tanúsítványellenőrzés kihagyása",
"linkcard.insecure_hint": "Saját szerverhez vagy lejárt tanúsítványú oldalhoz. Itt érvényes, mert a kapcsolatot ez a számítógép építi fel.",
"linkcard.install": "Telepítés hivatkozásról",
"linkcard.mode.direct": "A PS5 töltse le",
"linkcard.mode.direct_body": "A PS5 maga kéri le a hivatkozást. El kell érnie a hivatkozást, és a címnek rövidnek kell lennie (a hosszút az alkalmazás lerövidíti, és ilyenkor nyitva kell maradnia).",
"linkcard.mode.download": "Előbb letöltés ide, aztán telepítés",
"linkcard.mode.download_body": "Ez a számítógép elmenti a teljes csomagot, majd telepíti. Ez a leglassabb mód, de ha a hivatkozás lejár vagy megszakad, csak a letöltést kell újrapróbálni.",
"linkcard.mode.stream": "Streamelés ezen a számítógépen keresztül",
"linkcard.mode.stream_body": "Ez a számítógép több kapcsolattal tölt le, és azonnal továbbadja a PS5-nek. Általában ez a leggyorsabb, és akkor is működik, ha a hivatkozást csak ez a számítógép éri el.",
"linkcard.name": "Név (nem kötelező)",
"linkcard.name_hint": "A név a cím helyett jelenik meg a sorban, a Feladatok között és a legutóbbi hivatkozásoknál, így meg tudod különböztetni a hivatkozásokat, és a megfelelőt próbálhatod újra.",
