"linkcard.use": "Használat",
"install.description.v2": "Telepíts .pkg és .fpkg csomagokat a PS5-re: közvetlenül erről a számítógépről vagy hivatkozásról (Streamelés és telepítés), illetve egy előbb a PS5-re tett másolatból (Feltöltés és telepítés).",
