health_junk_explain_v2: "Amit a ps5upload hozott létre, és már nincs rá szükség: megszakadt átvitelek után maradt befejezetlen fájlok, az ideiglenes mappában több mint egy órája heverő csomagmásolatok és régi sebességteszt-fájlok. Csak a ps5upload saját mappáit nézzük át; a játékaidhoz, csomagjaidhoz és mentéseidhez soha nem nyúlunk.",
