"speedtest.verdict.hundred": "Ez 100 Mbites kapcsolatnak tűnik, amelynek a határa nagyjából 11 MB/s. Ellenőrizd a kábelt (Cat5e vagy jobb), és hogy az útvonalon a switch vagy router minden portja gigabites-e.",
