"pkg.sony_80b21104": "A PS5 nem fogadta el ezt a csomagot (0x80B21104). Ha más csomagok települnek erre a konzolra, a gond ezzel a fájllal van: legtöbbször egy új játék, amelynek csomagja újabb eszközökkel készült, mint amit a konzol firmware-e megért, vagy olyan csomag, amely nem hamis aláírású (FPKG) build. Használj a firmware-edhez készült csomagot (backport), vagy telepítsd a játékot a telepítő nélkül: másold fel a játékmappáját vagy egy ShadowMount+ játékképfájlt (.exfat vagy .ffpfsc) a Feltöltéssel.",
