sendpayload_probe_invalid_ext: "A payloadnak .elf, .bin, .js, .lua vagy .jar fájlnak kell lennie.",
sendpayload_probe_no_signature: "Nem található PS5Upload aláírás — csak akkor használd, ha megbízol ebben a payloadban.",
sendpayload_probe_ok: "A payload fájl rendben lévőnek tűnik.",
sendpayload_probe_read_error: "Nem sikerült beolvasni ezt a fájlt ({error}). Ellenőrizd, hogy még létezik és megnyitható, majd válaszd ki újra.",
sendpayload_probe_too_small: "Ez a fájl üres, így nincs mit elküldeni.",
servers_subtitle: "A NAS-aid és kiszolgálóid (SMB, FTP, FTPS, SFTP). Bárhol, ahol játékot vagy fájlt tallózol, a Tallózás melletti ▾ segítségével választhatsz közülük.",
settings_artwork_cache_explain_v2: "A játékborítók ott tárolódnak, ahol a motor fut (ezen a számítógépen, vagy a webes verziónál a kiszolgálón), így azonnal betöltődnek ahelyett, hogy minden alkalommal a PS5-ről kellene beolvasni őket. Automatikusan frissülnek, és egy konzolnál törlődnek, amikor ott játékot telepítesz vagy eltávolítasz.",
settings_backup_downloaded: "Letöltve: {name}",
settings_backup_hint_v2: "A téma, a PS5-lista, az értesítési előzmények, a tevékenységnapló és más beállítások egyetlen JSON-fájlba csomagolása, hogy visszaállíthasd őket az alkalmazás tárhelyének törlése után vagy egy másik gépen. A konzolpárosítások, a Gyűjtemény, a mentett kiszolgálók jelszavai és a backport könyvtárak nem kerülnek bele.",
settings_backup_restored: "{count} beállítás visszaállítva. Indítsd újra az alkalmazást, hogy minden módosítás érvénybe lépjen.",
settings_backup_saved: "Mentve ide: {path}",
settings_card_console_rest: "Pihenő mód",
settings_card_install_fallback: "Ha a PS5 nem tud letölteni egy csomagot",
settings_card_system_files: "Rendszerfájlok",
settings_file_hint_v2: "A fő beállítások (téma, nyelv, motor, mentési útvonal, feltöltési alapértelmezések, akadálymentesség, oldalsáv) ebbe a JSON-fájlba is tükröződnek. Kézzel is szerkesztheted; a módosítások az alkalmazás következő indításakor lépnek érvénybe. Nem tartalmaz mindent: az összes beállítás átviteléhez használd a biztonsági mentést / visszaállítást.",
settings_group_console: "Konzol",
settings_group_fakelibs: "Backportolás",
settings_group_files_saves: "Fájlok és mentések",
settings_group_installs: "Telepítések",
settings_schedule_label_placeholder_v2: "Címke (pl. mentések biztonsági mentése)",
settings_updates_browser_note: "Ezt a weboldalt a ps5upload motor szolgálja ki, és vele együtt frissül: töltsd le az új Docker image-et (vagy frissítsd a motort a kiszolgálón), és indítsd újra.",
show_file_list_hint_v2: "A Feltöltés képernyőn a küldött fájlok listája a folyamatjelző alatt. Kapcsold ki, ha a lista zavaró több ezer fájlt tartalmazó mappáknál — az összesített haladás, a sebesség és a hátralévő idő továbbra is látható.",
show_file_list_v2: "Fájllista megjelenítése feltöltés közben",
stats_description_v2: "Összesítések az ehhez a konzolhoz megjelenített műveletekről. Az alkalmazás az utolsó {count} műveletet tartja meg, így a régebbiek nem számítanak bele. Helyi előzményekből számolva; semmi sem hagyja el a gépedet.",
status_keep_awake_tooltip_v2: "Az ébren tartás „Mindig, amíg csatlakoztatva van” módra van állítva — a csatlakoztatott konzolok nem lépnek automatikusan pihenő módba, amíg az alkalmazás nyitva van. Módosítás: Beállítások → Konzol.",
update_idle_v2: "Még nincs ellenőrizve. Bekapcsolt automatikus ellenőrzés mellett az alkalmazás indításkor a háttérben ellenőriz, legfeljebb naponta egyszer.",
upload_auto_resume_hint_browser: "Ha egy feltöltés átvitel közben megszakad, folytatja onnan, ahol abbamaradt, amint a PS5 segédprogramja ismét válaszol, és néhányszor újrapróbálkozik, mielőtt feladja. Ez az oldal maga nem tudja újraküldeni a segédprogramot: ha a PS5 újraindult, előbb küldd el újra. A végzetes problémák, például ha a PS5-ön elfogy a hely, továbbra is azonnal leállítják. Alapértelmezetten bekapcsolva.",
upload_picker_from_ps5_hint: "Másik PS5-ről másolsz? Jelöld ki a fájlokat a Fájlrendszerben, és válaszd a Küldés másik konzolra lehetőséget.",
usb_wizard_title_v2: "USB payload pendrive",
videos_description_browser: "A PS5-ön (a Rögzítési galériában) mentett videoklipek. Töltsd le őket változtatás nélkül egy mappába azon a számítógépen, amelyen a ps5upload fut; nincs szükség konvertálásra. Törléshez használd a Fájlokat.",
autoloader_title_v2: "Lejátszási lista csatlakozáskor",
autoloader_warn_none_v2: "Válassz egy lejátszási listát, amely csatlakozáskor fut.",
backup_explain_v2: "Fájlokat másol egy pillanatképbe a konzol saját tárhelyén, hogy később visszatehesd őket. Válassz egy gyakori elemet lent, vagy írd be a saját útvonaladat.",
backup_limit_depth: "A kiválasztottnál {n} szintnél mélyebben lévő mappák kimaradnak.",
